import { expect, test } from "./fixtures";

// Loading the engine means fetching and compiling ~35 MB of WebAssembly.
const ENGINE_TIMEOUT = 60_000;
// Samples are generated by the engine when they're loaded.
const SAMPLE_TIMEOUT = 30_000;
// Even small queries can take seconds in WebKit on a busy machine.
const QUERY_TIMEOUT = 20_000;

test.describe("Templates", () => {
  test("runs a template on its sample data and opens its chart", async ({
    page,
    makeAxeBuilder,
  }) => {
    await page.goto("/app/");
    await expect(page.getByRole("status")).toHaveText(/^Engine ready/, { timeout: ENGINE_TIMEOUT });

    await page.getByRole("button", { name: "Templates" }).click();
    await page.getByRole("button", { name: /^Reject rate by machine/ }).click();
    const dialog = page.getByRole("dialog", { name: "Reject rate by machine" });
    await expect(dialog.getByRole("button", { name: "Run" })).toBeDisabled();

    await dialog.getByRole("button", { name: "Load sample data" }).click();
    await expect(dialog.getByLabel("Table")).toHaveValue("quality_checks");
    await expect(dialog.getByLabel("Machine")).toHaveValue("machine_id");
    const scan = await makeAxeBuilder().include('[role="dialog"]').analyze();
    expect(scan.violations).toEqual([]);

    await dialog.getByRole("button", { name: "Run" }).click();
    await expect(dialog).toBeHidden();
    await expect(page.getByRole("button", { name: "Chart" })).toHaveAttribute(
      "aria-pressed",
      "true",
    );
    await expect(
      page.getByRole("img", { name: /^Bar chart of avg\(reject_rate_pct\) by machine_id/ }),
    ).toBeVisible();
  });

  test("moves focus to the form's first field and back to the chosen template", async ({
    page,
  }) => {
    await page.goto("/app/");

    await page.getByRole("button", { name: "Templates" }).click();
    const chosen = page.getByRole("button", { name: /^Cost per kg by lane and carrier/ });
    await chosen.focus();
    await page.keyboard.press("Enter");

    const form = page.getByRole("dialog", { name: "Cost per kg by lane and carrier" });
    await expect(form.getByLabel("Table")).toBeFocused();

    await form.getByRole("button", { name: "All templates" }).press("Enter");
    await expect(chosen).toBeFocused();
  });

  test("keeps Close in view and scrolls the gallery to its last template", async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    await page.goto("/app/");

    await page.getByRole("button", { name: "Templates" }).click();
    const dialog = page.getByRole("dialog", { name: "Templates" });
    const close = dialog.getByRole("button", { name: "Close" });
    await expect(close).toBeInViewport({ ratio: 1 });

    const last = dialog.getByRole("button", { name: /^Two-file reconciliation/ });
    await last.scrollIntoViewIfNeeded();
    const box = await dialog.boundingBox();
    const card = await last.boundingBox();
    const closeBox = await close.boundingBox();
    if (!box || !card || !closeBox) throw new Error("Templates gallery not shown");

    expect(card.y).toBeGreaterThanOrEqual(box.y);
    expect(card.y + card.height).toBeLessThanOrEqual(closeBox.y);
    expect(closeBox.y + closeBox.height).toBeLessThanOrEqual(box.y + box.height);
  });

  for (const { title, chart } of [
    { title: "On-time delivery by carrier", chart: /^Bar chart of avg\(on_time_pct\) by carrier/ },
    { title: "Delivery lead time by lane", chart: /^Bar chart of avg\(p90_days\) by lane/ },
    {
      title: "Cost per kg by lane and carrier",
      chart: /^Bar chart of avg\(cost_per_kg\) by carrier/,
    },
  ]) {
    test(`runs ${title} on the shipments sample`, async ({ page }) => {
      test.setTimeout(120_000);
      await page.goto("/app/");
      await expect(page.getByRole("status")).toHaveText(/^Engine ready/, {
        timeout: ENGINE_TIMEOUT,
      });

      await page.getByRole("button", { name: "Templates" }).click();
      await page.getByRole("button", { name: new RegExp(`^${title}`) }).click();
      const dialog = page.getByRole("dialog", { name: title });
      await dialog.getByRole("button", { name: "Load sample data" }).click();
      await expect(dialog.getByLabel("Table")).toHaveValue("shipments", {
        timeout: SAMPLE_TIMEOUT,
      });

      await dialog.getByRole("button", { name: "Run" }).click();
      await expect(dialog).toBeHidden();
      await expect(page.getByRole("img", { name: chart })).toBeVisible({ timeout: QUERY_TIMEOUT });
    });
  }
});
